  /// product-specific attributes.
  key String

  /// The option value representing the specific selection for this key (e.g.,
  /// 'Red', 'Large', 'Cotton').
  ///
  /// Values are the actual option selections that distinguish variants from
  /// each other within the same product.
  value String

  /// Timestamp when this option entry was created as part of the product
  /// snapshot.
  ///
  /// This field records when the snapshot was generated, capturing the exact
  /// moment of the product modification.
  created_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  productSnapshotVariant shopping_mall_product_snapshot_variants @relation(fields: [shopping_mall_product_snapshot_variant_id], references: [id], onDelete: Cascade, map: "shopping_mall_product_snapshot_variant_options_shoppin_2222a9ef")

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@unique([shopping_mall_product_snapshot_variant_id, key], map: "shopping_mall_product_snapshot_variant_options_shoppin_64a5d87a")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_snapshot_variant_id], map: "shopping_mall_product_snapshot_variant_options_shoppin_3f9c4075")
}

