  TestValidator.equals("email matches", loggedInSeller.email, sellerEmail);
  TestValidator.equals(
    "approval status is approved",
    loggedInSeller.approval_status,
    "approved",
  );
  TestValidator.equals(
    "suspended flag is true",
    loggedInSeller.suspended,
    true,
  );
