  const now = new Date();
  const oneMonthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
  const dateRangeProfiles =
    await api.functional.shoppingMall.customer.profiles.index(
      customerConnection,
      {
        body: {
          created_after: oneMonthAgo.toISOString(),
