      productId: productB.id,
      body: {} satisfies IShoppingMallProduct.IUpdate,
    });
  typia.assert(refreshedProductB);
  TestValidator.equals(
    "Product B name unchanged",
    refreshedProductB.name,
    "Product B",
  );
}

