/**
 * Test the primary success path for reordering product images.
 *
 * Validates the complete product image reordering workflow including seller authentication, product creation, image uploads, and image reordering. Ensures that when images are reordered, they receive new display_order values based on their position in the request array, with the first image becoming the main thumbnail (display_order = 1).
 *
 * Special attention is given to verifying that the response returns the first image with display_order = 1 and that all image IDs in the request belong to the specified product owned by the authenticated seller.
 *
 * 1. Seller registers and authenticates to obtain access token.
 * 2. Seller creates a product with name, description, and base price.
 * 3. Seller uploads three images to the product for reordering testing.
 * 4. Seller reorders images by sending image IDs in reversed order.
 * 5. Validates that the returned image has display_order = 1 (main thumbnail).
 * 6. Validates that the first image in the new order is the one specified as first in the request.
 * 7. Fetches the product to verify all images are correctly reordered in the product's images array.
 */
export async function test_api_product_image_reorder_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller authentication
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 2. Create a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 3. Upload three images to the product
  const image1 =
    await generate_random_shopping_mall_seller_products_images_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(image1);
  const image2 =
    await generate_random_shopping_mall_seller_products_images_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(image2);
  const image3 =
    await generate_random_shopping_mall_seller_products_images_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(image3);
  // 4. Reorder images in reversed order (image3, image2, image1)
  const reordered =
    await api.functional.shoppingMall.seller.products.images.patchByProductid(
      sellerConnection,
      {
        productId: product.id,
        body: {
          images: [image3.id, image2.id, image1.id],
        } satisfies IShoppingMallProductImage.IReorder,
      },
    );
  typia.assert(reordered);
  // 5. Validate that the returned image has display_order = 1 (main thumbnail)
  TestValidator.equals(
    "first image in new order has display_order 1",
    reordered.display_order,
    1,
  );
  // 6. Validate that the first image in the new order is image3 (main thumbnail)
  TestValidator.equals(
    "main thumbnail is image3 after reordering",
    reordered.id,
    image3.id,
  );
  // 7. Verify display_order is a valid positive integer
  TestValidator.predicate(
    "display_order is valid positive integer",
    reordered.display_order >= 1,
  );
  // 8. Fetch the product to verify all images are correctly reordered
  const updatedProduct =
    await api.functional.shoppingMall.seller.products.create(sellerConnection, {
      body: product,
    });
}

