import { generate_random_shopping_mall_seller_products_create } from "../../../generate/generate_random_shopping_mall_seller_products_create";
import { prepare_random_shopping_mall_product } from "../../../prepare/prepare_random_shopping_mall_product";

/**
 * Test that a seller cannot access product snapshots belonging to another seller.
 *
 * Validates the authorization mechanism for product snapshot access, ensuring that sellers can only view snapshots of their own products. This test verifies that the system properly isolates seller data and prevents unauthorized cross-seller access to audit trail information.
 *
 * The test creates two separate seller accounts, generates a product snapshot owned by Seller A, then attempts to access that snapshot using Seller B's credentials. The system should reject this unauthorized access attempt with a 403 Forbidden error.
 *
 * 1. Register and authenticate Seller A with unique credentials.
 * 2. Seller A creates a product with name, description, and base price.
 * 3. Seller A updates the product to trigger snapshot creation.
 * 4. Register and authenticate Seller B with different credentials.
 * 5. Seller B attempts to retrieve Seller A's product snapshot.
 * 6. Verify that the access attempt fails with an HTTP error (403 Forbidden).
 */
export async function test_api_product_snapshot_unauthorized_seller_access(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate Seller A
  const sellerAConnection: api.IConnection = { host: connection.host };
  const sellerA = await authorize_seller_join(sellerAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "password123",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerA);
  // 2. Seller A creates a product
  const product = await api.functional.shoppingMall.seller.products.create(
    sellerAConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 3. Seller A updates the product to create a snapshot
  const updatedProduct =
    await api.functional.shoppingMall.seller.products.update(
      sellerAConnection,
      {
        productId: product.id,
        body: {
          name: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IShoppingMallProduct.IUpdate,
      },
    );
  typia.assert(updatedProduct);
  // Generate a snapshot ID for the test
  // The backend should validate seller ownership before checking snapshot existence
  const snapshotId = typia.random<string & tags.Format<"uuid">>();
  // 4. Register and authenticate Seller B
  const sellerBConnection: api.IConnection = { host: connection.host };
  const sellerB = await authorize_seller_join(sellerBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "password456",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerB);
  // 5. Seller B attempts to access Seller A's product snapshot
  // This should fail with 403 Forbidden due to unauthorized access
  await TestValidator.httpError(
    "unauthorized seller cannot access another seller's snapshot",
    403,
    async () =>
      await api.functional.shoppingMall.seller.products.snapshots.at(
        sellerBConnection,
        {
          productId: product.id,
          snapshotId: snapshotId,
        },
      ),
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test browsing all available product categories on the platform.
 *
 * Validates the public category listing endpoint that returns a paginated list of all non-deleted categories. This test ensures that categories are returned with complete information including hierarchical parent relationships, and that soft-deleted categories are properly excluded from results.
 *
 * The test verifies pagination metadata accuracy, category field completeness, and the correct handling of parent category references (null for top-level categories, ISummary for subcategories).
 *
 * 1. Calls the public endpoint with an empty request body to retrieve all categories
 * 2. Validates the response structure and pagination metadata
 * 3. Verifies each category has all required fields and valid parent relationships
 * 4. Confirms that all returned categories have deleted_at set to null
 */
export async function test_api_category_list_all_categories(
  connection: api.IConnection,
): Promise<void> {
  // 1. Call the public endpoint to list all categories
  const output = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {} satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(output);
  // 2. Validate pagination metadata
  TestValidator.predicate(
    "pagination current page is at least 1",
    output.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit is positive",
    output.pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination records count is non-negative",
    output.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages count is non-negative",
    output.pagination.pages >= 0,
  );
  // 3. Validate data array exists
  TestValidator.predicate("data array exists", Array.isArray(output.data));
  // 4. Validate each category in the response
  await ArrayUtil.asyncForEach(output.data, async (category) => {
    // Validate required fields exist
    TestValidator.predicate(
      `category has valid UUID: ${category.id}`,
      typeof category.id === "string" && category.id.length > 0,
    );
    TestValidator.predicate(
      `category has name: ${category.name}`,
      typeof category.name === "string" && category.name.length > 0,
    );
    TestValidator.predicate(
      `category has description: ${category.description}`,
      typeof category.description === "string",
    );
    TestValidator.predicate(
      `category has created_at: ${category.created_at}`,
      typeof category.created_at === "string",
    );
    TestValidator.predicate(
      `category has updated_at: ${category.updated_at}`,
      typeof category.updated_at === "string",
    );
    // Validate parentCategory is either null or a valid ISummary
    if (category.parentCategory === null) {
      TestValidator.predicate(
        `top-level category has null parent: ${category.name}`,
        category.parentCategory === null,
      );
    } else {
      TestValidator.predicate(
        `subcategory has valid parent: ${category.name}`,
        typeof category.parentCategory.id === "string" &&
          typeof category.parentCategory.name === "string",
      );
    }
    // Validate deleted_at is null (soft-deleted categories should be excluded)
    TestValidator.equals(
      `category is not deleted: ${category.name}`,
      category.deleted_at,
      null,
    );
  });
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test filtering categories by their parent-child relationship to support hierarchical browsing.
 *
 * Validates the category filtering functionality that enables hierarchical navigation through parent and subcategory relationships. Tests that categories can be filtered by whether they have a parent, by specific parent ID, and that the hierarchical relationships are correctly represented in responses.
 *
 * The test verifies that the parent-child relationship filtering works correctly for both top-level categories and subcategories, ensuring proper data structure and pagination support.
 *
 * 1. Fetch all categories to identify top-level and subcategory examples
 * 2. Filter by hasParent=true to verify only subcategories are returned
 * 3. Filter by hasParent=false to verify only top-level categories are returned
 * 4. Filter by parentId to verify only direct children of a specific parent are returned
 * 5. Filter by invalid parentId to verify empty results are returned
 * 6. Validate that parentCategory field correctly represents hierarchical relationships
 * 7. Verify pagination metadata is accurate for filtered results
 */
export async function test_api_category_filter_by_parent_relationship(
  connection: api.IConnection,
): Promise<void> {
  // 1. Fetch all categories to identify examples
  const allCategories = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        limit: 100,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(allCategories);
  // Separate top-level and subcategories for testing
  const topLevelCategories = allCategories.data.filter(
    (cat) => cat.parentCategory === null,
  );
  const subcategories = allCategories.data.filter(
    (cat) => cat.parentCategory !== null,
  );
  // 2. Test hasParent=true filter (should return only subcategories)
  const hasParentResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        hasParent: true,
        limit: 100,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(hasParentResult);
  TestValidator.equals(
    "hasParent=true returns only subcategories",
    hasParentResult.data.length,
    subcategories.length,
  );
  TestValidator.predicate(
    "all results have parent",
    hasParentResult.data.every((cat) => cat.parentCategory !== null),
  );
  // 3. Test hasParent=false filter (should return only top-level categories)
  const hasParentFalseResult =
    await api.functional.shoppingMall.categories.index(connection, {
      body: {
        hasParent: false,
        limit: 100,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(hasParentFalseResult);
  TestValidator.equals(
    "hasParent=false returns only top-level categories",
    hasParentFalseResult.data.length,
    topLevelCategories.length,
  );
  TestValidator.predicate(
    "all results have no parent",
    hasParentFalseResult.data.every((cat) => cat.parentCategory === null),
  );
  // 4. Test parentId filter with valid parent
  if (topLevelCategories.length > 0) {
    const parentCategory = topLevelCategories[0];
    const parentIdResult = await api.functional.shoppingMall.categories.index(
      connection,
      {
        body: {
          parentId: parentCategory.id,
          limit: 100,
        } satisfies IShoppingMallCategory.IRequest,
      },
    );
    typia.assert(parentIdResult);
    // All results should be direct children of the specified parent
    TestValidator.predicate(
      "all results have correct parent",
      parentIdResult.data.every(
        (cat) => cat.parentCategory?.id === parentCategory.id,
      ),
    );
    // Verify parentCategory field is correctly populated
    if (parentIdResult.data.length > 0) {
      TestValidator.equals(
        "parentCategory name matches",
        parentIdResult.data[0].parentCategory?.name,
        parentCategory.name,
      );
    }
  }
  // 5. Test parentId filter with invalid parent (non-existent UUID)
  const invalidParentIdResult =
    await api.functional.shoppingMall.categories.index(connection, {
      body: {
        parentId: "00000000-0000-0000-0000-000000000000",
        limit: 100,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(invalidParentIdResult);
  TestValidator.equals(
    "invalid parentId returns empty results",
    invalidParentIdResult.data.length,
    0,
  );
  TestValidator.equals(
    "invalid parentId pagination records is 0",
    invalidParentIdResult.pagination.records,
    0,
  );
  // 6. Test pagination with hasParent filter
  const paginatedResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        hasParent: true,
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(paginatedResult);
  TestValidator.equals(
    "pagination limit respected",
    paginatedResult.pagination.limit,
    10,
  );
  TestValidator.equals(
    "pagination current page is 1",
    paginatedResult.pagination.current,
    1,
  );
  TestValidator.predicate(
    "data count matches limit or records",
    paginatedResult.data.length <= paginatedResult.pagination.limit,
  );
  TestValidator.predicate(
    "pages calculated correctly",
    paginatedResult.pagination.pages ===
      Math.ceil(
        paginatedResult.pagination.records / paginatedResult.pagination.limit,
      ),
  );
  // 7. Test sorting with hasParent filter
  const sortedAscResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        hasParent: false,
        sortBy: "name",
        sortOrder: "ASC",
        limit: 100,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(sortedAscResult);
  const sortedDescResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        hasParent: false,
        sortBy: "name",
        sortOrder: "DESC",
        limit: 100,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(sortedDescResult);
  // Verify sorting order
  if (sortedAscResult.data.length > 1) {
    const namesAsc = sortedAscResult.data.map((cat) => cat.name);
    const namesDesc = sortedDescResult.data.map((cat) => cat.name);
    const namesAscReversed = [...namesAsc].reverse();
    TestValidator.equals(
      "DESC order is reverse of ASC order",
      namesDesc,
      namesAscReversed,
    );
  }
  // 8. Validate response structure consistency
  if (hasParentResult.data.length > 0) {
    const sampleCategory = hasParentResult.data[0];
    // Verify all required fields are present
    TestValidator.predicate(
      "category has valid UUID",
      /^[0-9a-f-]{36}$/i.test(sampleCategory.id),
    );
    TestValidator.predicate(
      "category has name",
      sampleCategory.name.length > 0,
    );
    TestValidator.predicate(
      "category has description",
      sampleCategory.description.length >= 0,
    );
    TestValidator.predicate(
      "category has created_at",
      /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}/.test(
        sampleCategory.created_at,
      ),
    );
    TestValidator.predicate(
      "category has updated_at",
      /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}/.test(
        sampleCategory.updated_at,
      ),
    );
    TestValidator.predicate(
      "category is not deleted",
      sampleCategory.deleted_at === null,
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test advanced category search capabilities with text filtering and pagination controls.
 *
 * Validates the complete category search functionality including partial text matching for name and description fields, pagination parameter handling, sorting options, and pagination metadata accuracy. Ensures that search filters use case-insensitive partial matching and that pagination correctly reflects the filtered dataset size.
 *
 * Special attention is given to verifying that multiple filters combine with AND logic, pagination parameters are properly bounded, and sorting respects both field and direction specifications.
 *
 * 1. Execute search with empty criteria to retrieve all non-deleted categories.
 * 2. Validate pagination metadata (current page, limit, total records, total pages).
 * 3. Test name filter with partial text matching using actual category data.
 * 4. Test description filter with partial text matching using actual category data.
 * 5. Test combined name and description filters (AND logic).
 * 6. Test pagination with page and limit parameters.
 * 7. Test sorting by different fields with ASC/DESC order.
 * 8. Verify pagination metadata accuracy for filtered results.
 */
export async function test_api_category_search_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Search with empty criteria - retrieve all non-deleted categories
  const allCategories = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: { limit: 50 } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(allCategories);
  TestValidator.predicate(
    "has pagination metadata",
    allCategories.pagination.current >= 1,
  );
  TestValidator.predicate(
    "has valid limit",
    allCategories.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "has total records count",
    allCategories.pagination.records >= 0,
  );
  TestValidator.predicate(
    "has total pages",
    allCategories.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "data array exists",
    Array.isArray(allCategories.data),
  );
  // Need at least one category to test search functionality
  if (allCategories.data.length === 0) {
    TestValidator.predicate("test skipped - no categories exist", true);
    return;
  }
  // 2. Test name filter with partial text matching using actual category name
  const sampleCategory = allCategories.data[0];
  const searchName = sampleCategory.name.substring(
    0,
    Math.max(1, Math.floor(sampleCategory.name.length / 2)),
  );
  const nameFilterResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        name: searchName,
        limit: 20,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(nameFilterResult);
  // Verify all returned categories contain the search term in name (case-insensitive)
  for (const category of nameFilterResult.data) {
    TestValidator.predicate(
      `category name contains search term "${searchName}"`,
      category.name.toLowerCase().includes(searchName.toLowerCase()),
    );
  }
  // 3. Test description filter with partial text matching
  const searchDescription = sampleCategory.description.substring(
    0,
    Math.max(1, Math.floor(sampleCategory.description.length / 2)),
  );
  const descriptionFilterResult =
    await api.functional.shoppingMall.categories.index(connection, {
      body: {
        description: searchDescription,
        limit: 20,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(descriptionFilterResult);
  // Verify all returned categories contain the search term in description (case-insensitive)
  for (const category of descriptionFilterResult.data) {
    TestValidator.predicate(
      `category description contains search term "${searchDescription}"`,
      category.description
        .toLowerCase()
        .includes(searchDescription.toLowerCase()),
    );
  }
  // 4. Test pagination with page and limit parameters
  const paginatedResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(paginatedResult);
  TestValidator.equals(
    "current page is 1",
    paginatedResult.pagination.current,
    1,
  );
  TestValidator.equals("limit is 10", paginatedResult.pagination.limit, 10);
  TestValidator.predicate(
    "data count does not exceed limit",
    paginatedResult.data.length <= 10,
  );
  // Test page 2 if enough records exist
  if (allCategories.pagination.records > 10) {
    const page2Result = await api.functional.shoppingMall.categories.index(
      connection,
      {
        body: {
          page: 2,
          limit: 10,
        } satisfies IShoppingMallCategory.IRequest,
      },
    );
    typia.assert(page2Result);
    TestValidator.equals(
      "current page is 2",
      page2Result.pagination.current,
      2,
    );
  }
  // 5. Test sorting by name in ascending order
  const sortedByNameAsc = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        sortBy: "name",
        sortOrder: "ASC",
        limit: 20,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(sortedByNameAsc);
  // Verify ascending order by name
  for (let i = 1; i < sortedByNameAsc.data.length; i++) {
    const prevCategory = sortedByNameAsc.data[i - 1];
    const currentCategory = sortedByNameAsc.data[i];
    TestValidator.predicate(
      `categories sorted by name ASC at index ${i}`,
      prevCategory.name.localeCompare(currentCategory.name) <= 0,
    );
  }
  // 6. Test descending sort order
  const sortedByNameDesc = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        sortBy: "name",
        sortOrder: "DESC",
        limit: 20,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(sortedByNameDesc);
  // Verify descending order by name
  for (let i = 1; i < sortedByNameDesc.data.length; i++) {
    const prevCategory = sortedByNameDesc.data[i - 1];
    const currentCategory = sortedByNameDesc.data[i];
    TestValidator.predicate(
      `categories sorted by name DESC at index ${i}`,
      prevCategory.name.localeCompare(currentCategory.name) >= 0,
    );
  }
  // 7. Test hasParent filter for subcategories
  const hasParentResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        hasParent: true,
        limit: 15,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(hasParentResult);
  // Verify all returned categories have a parent
  for (const category of hasParentResult.data) {
    TestValidator.predicate(
      "subcategory has parent category",
      category.parentCategory !== null,
    );
  }
  // 8. Test hasParent filter for top-level categories
  const noParentResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        hasParent: false,
        limit: 15,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(noParentResult);
  // Verify all returned categories have no parent (top-level)
  for (const category of noParentResult.data) {
    TestValidator.predicate(
      "top-level category has no parent",
      category.parentCategory === null,
    );
  }
  // 9. Test parentId filter if subcategories exist
  if (
    hasParentResult.data.length > 0 &&
    hasParentResult.data[0].parentCategory !== null
  ) {
    const parentId = hasParentResult.data[0].parentCategory.id;
    const parentIdResult = await api.functional.shoppingMall.categories.index(
      connection,
      {
        body: {
          parentId: parentId,
          limit: 10,
        } satisfies IShoppingMallCategory.IRequest,
      },
    );
    typia.assert(parentIdResult);
    // Verify all returned categories have the specified parent
    for (const category of parentIdResult.data) {
      TestValidator.equals(
        "category has specified parent",
        category.parentCategory?.id,
        parentId,
      );
    }
  }
  // 10. Verify pagination metadata consistency
  TestValidator.predicate(
    "pages calculated correctly",
    allCategories.pagination.pages ===
      Math.ceil(
        allCategories.pagination.records / allCategories.pagination.limit,
      ),
  );
  // 11. Test limit boundary (minimum 1, maximum 100)
  const minLimitResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        limit: 1,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(minLimitResult);
  TestValidator.equals(
    "limit of 1 returns at most 1 record",
    minLimitResult.data.length,
    Math.min(1, allCategories.pagination.records),
  );
  const maxLimitResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        limit: 100,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(maxLimitResult);
  TestValidator.equals(
    "max limit is 100",
    maxLimitResult.pagination.limit,
    Math.min(100, allCategories.pagination.records),
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
