/**
 * Test cancellation request snapshot filtering by status transition (approved vs rejected).
 *
 * Validates that customers can filter cancellation request snapshots by status transitions to analyze seller response patterns. The test creates multiple cancellation requests with different outcomes (approved and rejected) and verifies that the snapshot filtering correctly separates them.
 *
 * 1. Register and authenticate a customer
 * 2. Register and authenticate a seller
 * 3. Seller creates two products with variants and inventory
 * 4. Customer adds variants to cart and places two separate orders
 * 5. Customer creates cancellation requests for items from both orders
 * 6. Seller approves the first cancellation request (creates 'approved' snapshot)
 * 7. Seller rejects the second cancellation request (creates 'rejected' snapshot)
 * 8. Customer filters snapshots by statusAfter='approved' and verifies only approved snapshots are returned
 * 9. Customer filters snapshots by statusAfter='rejected' and verifies only rejected snapshots are returned
 * 10. Validates that each filter returns accurate subsets with correct status transitions and seller response reasons
 */
export async function test_api_cancellation_request_snapshot_filter_by_status_transition(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: undefined,
  });
  typia.assert(customerAuth);
  // 2. Register and authenticate seller
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: undefined,
  });
  typia.assert(sellerAuth);
  // 3. Seller creates first product with variant
  const product1 = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    { body: undefined },
  );
  typia.assert(product1);
  const variant1 =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        body: { initialStockQuantity: 10 },
        params: { productId: product1.id },
      },
    );
  typia.assert(variant1);
  // 4. Seller creates second product with variant
  const product2 = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    { body: undefined },
  );
  typia.assert(product2);
  const variant2 =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        body: { initialStockQuantity: 10 },
        params: { productId: product2.id },
      },
    );
  typia.assert(variant2);
  // 5. Customer adds first variant to cart and places first order
  await generate_random_shopping_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        productVariantId: variant1.id,
        quantity: 1,
      },
    },
  );
  const order1 = await generate_random_shopping_mall_customer_checkout(
    customerConnection,
    { body: undefined },
  );
  typia.assert(order1);
  // 6. Customer adds second variant to cart and places second order
  await generate_random_shopping_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        productVariantId: variant2.id,
        quantity: 1,
      },
    },
  );
  const order2 = await generate_random_shopping_mall_customer_checkout(
    customerConnection,
    { body: undefined },
  );
  typia.assert(order2);
  // 7. Customer creates first cancellation request
  const cancellationRequest1 =
    await generate_random_shopping_mall_customer_cancellation_requests_create(
      customerConnection,
      {
        body: {
          orderItemId: order1.items[0].id,
          reason:
            "Customer wants to cancel this order item for testing purposes.",
        },
      },
    );
  typia.assert(cancellationRequest1);
  // 8. Customer creates second cancellation request
  const cancellationRequest2 =
    await generate_random_shopping_mall_customer_cancellation_requests_create(
      customerConnection,
      {
        body: {
          orderItemId: order2.items[0].id,
          reason:
            "Customer wants to cancel this order item for testing purposes.",
        },
      },
    );
  typia.assert(cancellationRequest2);
  // 9. Seller approves first cancellation request
  await api.functional.shoppingMall.seller.cancellation_requests.update(
    sellerConnection,
    {
      cancellationRequestId: cancellationRequest1.id,
      body: {
        status: "approved",
        response_reason: "Seller approved the cancellation request.",
      } satisfies IShoppingMallCancellationRequest.IUpdate,
    },
  );
  // 10. Seller rejects second cancellation request
  await api.functional.shoppingMall.seller.cancellation_requests.update(
    sellerConnection,
    {
      cancellationRequestId: cancellationRequest2.id,
      body: {
        status: "rejected",
        response_reason:
          "Seller rejected the cancellation request due to item already being prepared for shipment.",
      } satisfies IShoppingMallCancellationRequest.IUpdate,
    },
  );
  // 11. Customer filters snapshots by statusAfter='approved'
  const approvedSnapshots =
    await api.functional.shoppingMall.customer.cancellation_requests.snapshots.index(
      customerConnection,
      {
        body: {
          statusAfter: "approved",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(approvedSnapshots);
  // 12. Verify approved filter returns only approved snapshots
  TestValidator.equals(
    "approved snapshots count",
    approvedSnapshots.data.length,
    1,
  );
  TestValidator.equals(
    "approved snapshot status_before",
    approvedSnapshots.data[0].status_before,
    "pending",
  );
  TestValidator.equals(
    "approved snapshot status_after",
    approvedSnapshots.data[0].status_after,
    "approved",
  );
  TestValidator.predicate(
    "approved snapshot has seller response",
    approvedSnapshots.data[0].seller_response !== null,
  );
  // 13. Customer filters snapshots by statusAfter='rejected'
  const rejectedSnapshots =
    await api.functional.shoppingMall.customer.cancellation_requests.snapshots.index(
      customerConnection,
      {
        body: {
          statusAfter: "rejected",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(rejectedSnapshots);
  // 14. Verify rejected filter returns only rejected snapshots
  TestValidator.equals(
    "rejected snapshots count",
    rejectedSnapshots.data.length,
    1,
  );
  TestValidator.equals(
    "rejected snapshot status_before",
    rejectedSnapshots.data[0].status_before,
    "pending",
  );
  TestValidator.equals(
    "rejected snapshot status_after",
    rejectedSnapshots.data[0].status_after,
    "rejected",
  );
  TestValidator.predicate(
    "rejected snapshot has seller response",
    rejectedSnapshots.data[0].seller_response !== null,
  );
  // 15. Verify pagination metadata reflects filtered record counts
  TestValidator.equals(
    "approved pagination records",
    approvedSnapshots.pagination.records,
    1,
  );
  TestValidator.equals(
    "rejected pagination records",
    rejectedSnapshots.pagination.records,
    1,
  );
}

