/**
 * Test that a customer can retrieve their approved refund request with seller response details.
 *
 * Validates the complete refund request approval workflow including customer registration, seller registration, product creation with variants, order placement, shipment creation, delivery confirmation, refund request creation, and seller approval. Ensures that the refund request response contains accurate information including the customer's original reason, approved status, seller information, and timestamps.
 *
 * Special attention is given to verifying that the refund request correctly references the order item, that the status is 'approved' after seller approval, and that the seller field is populated with the responding seller's information.
 *
 * 1. Customer joins the platform with email and password.
 * 2. Seller joins the platform with email and password.
 * 3. Seller creates a product with name, description, and base price.
 * 4. Seller creates a product variant with SKU code, options, and initial stock.
 * 5. Customer adds the product variant to their shopping cart.
 * 6. Customer places an order through checkout.
 * 7. Seller creates a shipment for the order item with carrier and tracking number.
 * 8. Customer confirms delivery for the shipment.
 * 9. Customer creates a refund request for the delivered order item.
 * 10. Seller approves the refund request with a response reason.
 * 11. Customer retrieves the approved refund request by ID.
 * 12. Validates refund request details match expected values.
 */
export async function test_api_refund_request_retrieve_approved(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer joins the platform
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 2. Seller joins the platform
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 4. Seller creates a product variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: undefined,
      },
    );
  typia.assert(variant);
  // 5. Customer adds variant to cart
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          productVariantId: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // 6. Customer places order through checkout
  const order = await generate_random_shopping_mall_customer_checkout(
    customerConnection,
    {},
  );
  typia.assert(order);
  // 7. Seller creates shipment for the order item
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          carrier_name: "FedEx",
          tracking_number: "1234567890",
          order_item_ids: [order.items[0].id],
        },
      },
    );
  typia.assert(shipment);
  // 8. Customer confirms delivery
  await api.functional.shoppingMall.customer.orders.shipments.delivered.confirmDelivery(
    customerConnection,
    {
      orderId: order.id,
      shipmentId: shipment.id,
    },
  );
  // 9. Customer creates a refund request for the delivered item
  const refundRequest =
    await generate_random_shopping_mall_customer_orders_items_refund_create(
      customerConnection,
      {
        params: {
          orderId: order.id,
          itemId: order.items[0].id,
        },
        body: undefined,
      },
    );
  typia.assert(refundRequest);
  // 10. Seller approves the refund request
  const approvedRefund =
    await api.functional.shoppingMall.seller.orders.items.refund.approve(
      sellerConnection,
      {
        orderId: order.id,
        itemId: order.items[0].id,
        body: {
          responseText: "Refund approved due to product quality issue.",
        } satisfies IShoppingMallRefundRequest.IApprove,
      },
    );
  typia.assert(approvedRefund);
  // 11. Customer retrieves the approved refund request
  const retrievedRefund =
    await api.functional.shoppingMall.customer.refund_requests.at(
      customerConnection,
      {
        refundRequestId: refundRequest.id,
      },
    );
  typia.assert(retrievedRefund);
  // 12. Validate refund request details
  TestValidator.equals(
    "refund request ID matches",
    retrievedRefund.id,
    refundRequest.id,
  );
  TestValidator.equals(
    "status is approved",
    retrievedRefund.status,
    "approved",
  );
  TestValidator.predicate(
    "reason is not empty",
    retrievedRefund.reason.length > 0,
  );
  TestValidator.predicate(
    "seller is populated",
    retrievedRefund.seller !== null,
  );
  TestValidator.predicate(
    "responded_at is populated",
    retrievedRefund.responded_at !== null,
  );
  TestValidator.equals(
    "order item status is refunded",
    retrievedRefund.orderItem.status,
    "refunded",
  );
  TestValidator.equals(
    "customer matches",
    retrievedRefund.customer.id,
    String(customerConnection.headers?.Authorization ?? "").replace("Bearer ", ""),
  );
}

