    await api.functional.shoppingMall.administrator.administrator_requests.update(
      superAdminConnection,
      {
        administratorRequestId: request.id,
        body: {
          status: "approved",
        } satisfies IShoppingMallAdministratorRequest.IUpdate,
      },
    );
