    const status = expiredAt > now ? "active" : "expired";
    return {
      id: input.id,
      actorType: "guest",
      actorId: input.guest.id,
      actorEmail: "",
      ip: input.ip,
      href: input.href,
      created_at: input.created_at.toISOString(),
      expired_at: expiredAt.toISOString(),
      status,
    } satisfies IShoppingMallGuestSession.ISummary;
  }
