import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteShoppingMallCustomerCartItemsItemId(props: {
  customer: CustomerPayload;
  itemId: string;
}): Promise<void> {
  // 1. Find the cart item and verify it exists and is not deleted
  const cartItem =
    await MyGlobal.prisma.shopping_mall_customer_cart_items.findUniqueOrThrow({
      where: {
        id: props.itemId,
        deleted_at: null,
      },
      select: {
        id: true,
        shopping_mall_customer_cart_id: true,
      },
    });
  // 2. Verify the cart belongs to the authenticated customer
  const cart =
    await MyGlobal.prisma.shopping_mall_customer_carts.findUniqueOrThrow({
      where: {
        id: cartItem.shopping_mall_customer_cart_id,
      },
      select: {
        id: true,
        shopping_mall_customer_id: true,
      },
    });
  if (cart.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Forbidden", 403);
  }
  // 3. Delete the cart item
  await MyGlobal.prisma.shopping_mall_customer_cart_items.delete({
    where: { id: props.itemId },
  });
}

