        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a single order item snapshot by its unique identifier.
   *
   * This endpoint returns the complete snapshot data for a specific order item, including the product name, description, category, base price, variant SKU code and price, and seller shop information as they existed at the time of purchase. Snapshots are immutable records that preserve the exact state of purchased items regardless of subsequent product or seller profile changes.
   *
   * Access is restricted based on user role: customers can only view snapshots of items in their own orders, sellers can view snapshots of items containing their products, and administrators can view all snapshots on the platform.
   *
   * @param connection
